<?= $this->extend('admin/layout') ?><?= $this->section('content') ?><dl><dt>Total requests</dt><dd><?= (int)$total ?></dd><dt>Successful verifications</dt><dd><?= (int)$successful ?></dd><dt>Unsuccessful verifications</dt><dd><?= (int)$unsuccessful ?></dd></dl><form class="filters" method="get"><label>Result<select name="result"><option value="">All</option><?php foreach(['verified','not_enrolled','student_not_found','invalid_request','unauthorized'] as $v):?><option value="<?= $v ?>" <?= $result===$v?'selected':'' ?>><?= esc(str_replace('_',' ',$v)) ?></option><?php endforeach ?></select></label><label>Date<input type="date" name="date" value="<?= esc($date,'attr') ?>"></label><button>Filter</button></form><div class="table-wrap"><table><thead><tr><th>Timestamp (UTC)</th><th>Result</th><th>Response category</th><th>Student identifier hash</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><?= esc($log['requested_at']) ?></td><td><?= esc(str_replace('_',' ',$log['verification_result'])) ?></td><td><?= esc($log['response_category']) ?></td><td><code><?= esc($log['student_identifier_hash']??'Not supplied') ?></code></td></tr><?php endforeach ?></tbody></table></div><?= $pager ?><?= $this->endSection() ?>
